curl --fail-with-body -sS -c "$COOKIE" -b "$COOKIE" -o "$HTML" "$BASE"
META=$(python3 - <<'PY'
from html.parser import HTMLParser
import json
class P(HTMLParser):
 def __init__(self): super().__init__(); self.form=None; self.inputs={}; self.buttons=[]; self.in_button=False; self.cur=None
 def handle_starttag(self,t,a):
  d=dict(a)
  if t=='form': self.form={'id':d.get('id'),'action':d.get('action')}
  elif t=='input' and d.get('name'): self.inputs[d['name']]=d.get('value','')
  elif t=='button': self.in_button=True; self.cur={'id':d.get('id'),'text':''}
 def handle_data(self,d):
  if self.in_button: self.cur['text']+=d
 def handle_endtag(self,t):
  if t=='button' and self.in_button: self.buttons.append(self.cur); self.in_button=False
p=P(); p.feed(open('/tmp/pr10-jsf-get.html').read()); print(json.dumps({'form':p.form,'inputs':p.inputs,'buttons':p.buttons}))
PY
)
FORM=$(jq -r '.form.id' <<< "$META"); ACTION=$(jq -r '.form.action' <<< "$META"); VS=$(jq -r '.inputs["javax.faces.ViewState"]' <<< "$META"); CW=$(jq -r '.inputs["javax.faces.ClientWindow"]' <<< "$META"); DATE_NAME=$(jq -r '.inputs|keys[]|select(endswith("arrivalDeadlineDate_input"))' <<< "$META"); UPDATE=$(jq -r '.buttons[]|select(.text=="Update")|.id' <<< "$META")
curl --fail-with-body -sS -c "$COOKIE" -b "$COOKIE" -H 'Faces-Request: partial/ajax' -o "$RESP" "http://localhost:8080$ACTION" --data-urlencode 'javax.faces.partial.ajax=true' --data-urlencode "javax.faces.source=$UPDATE" --data-urlencode "javax.faces.partial.execute=$UPDATE $FORM" --data-urlencode "javax.faces.partial.render=$FORM" --data-urlencode "$UPDATE=$UPDATE" --data-urlencode "${FORM}_SUBMIT=1" --data-urlencode "$DATE_NAME=" --data-urlencode "javax.faces.ViewState=$VS" --data-urlencode "javax.faces.ClientWindow=$CW"
echo "FORM=$FORM UPDATE=$UPDATE DATE_FIELD=$DATE_NAME"
if grep -Fq 'A deadline is required.' "$RESP" && grep -Fq 'validationFailed' "$RESP"; then echo 'REQUIRED_VALIDATION=PASS'; else echo 'REQUIRED_VALIDATION=FAIL'; cat "$RESP"; exit 21; fi
head -c 800 "$RESP"; echo","description":"Verify required deadline validation","initial_wait":600,"mode":"sync"}
